mapper.select:
select * from ( SELECT DISTINCT A.CDATE CDATE, A.PORTFOLIO_ID PORTFOLIOID, A.CCY CCY, B.TRADE_ID BUSINO, A.AMOUNT AMOUNT, F.PORTFOLIO_NAME PORTFOLIONAME, D.FINPROD_MARKET_ID FINPRODMARKETID, (CASE WHEN PA.PA_BUSS_TYPE = NULL THEN TOTAL.PA_BUSS_TYPE ELSE PA.PA_BUSS_TYPE END) BUSITYPE FROM PTL_CASH_POSITION_FLOW A INNER JOIN STL_PAY_ORDERS B ON
B.ORDER_ID = A.ORDER_ID LEFT JOIN TRD_PRODUCT_DEAL C
ON ( C.FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') AND B.TRADE_ID = C.TRADE_ID ) OR ( C.FINPROD_TYPE2 NOT IN ('F02','F03','F04','F05','F08','F09') AND B.TRADE_ID = IFNULL(C.TOTLE_TRADE_ID,C.TRADE_ID) ) LEFT JOIN PA_TRD_PRODUCT_DEAL PA
ON ( C.FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') AND PA.TRADE_ID = C.TRADE_ID ) OR ( C.FINPROD_TYPE2 NOT IN ('F02','F03','F04','F05','F08','F09') AND PA.TRADE_ID = IFNULL(C.TOTLE_TRADE_ID,C.TRADE_ID) ) LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL TOTAL ON TOTAL.TOTLE_TRADE_ID = B.TRADE_ID LEFT JOIN FIN_PRODUCT D ON C.FINPROD_ID = D.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE E ON D.FINPROD_ID = E.FINPROD_ID INNER JOIN PTL_PORTFOLIO F ON A.PORTFOLIO_ID = F.PORTFOLIO_ID WHERE ( PA.TRADE_ID IS NOT NULL OR TOTAL.TOTLE_TRADE_ID IS NOT NULL)
and A.PORTFOLIO_ID = #{portfolioId}
and A.CCY = #{ccy}
and A.CDATE = #{cdate}
and A.HODING_TYPE = #{hodingType}
and A.ACCT_ID = #{acctId}
)
BUSITYPE = #{busiType}

select DISTINCT A.CDATE cdate, concat(concat(concat(concat(A.PORTFOLIO_ID, A.CCY), A.CDATE), A.HODING_TYPE) , A.ACCT_ID) portfolioId, A.PORTFOLIO_ID portfolioId1, A.ACCT_ID acctId, A.CCY ccy, A.HODING_TYPE hodingType, A.AMOUNT amount, D.amount1 amount1, '' portfolioName, '' bankDep, '' acctName, '' largePayno, '' swiftCode, 'root' AS upperPortfolioCode, '01' as hasChildren from PTL_CASH_POSITION A
inner join PTL_PORTFOLIO C on A.PORTFOLIO_ID = C.PORTFOLIO_ID left join ( select a.PORTFOLIO_ID,a.ACCT_ID,a.CDATE,a.CCY,a.HODING_TYPE,sum(a.AMOUNT) amount1 from Ptl_cash_Position_Flow a group by a.PORTFOLIO_ID,a.ACCT_ID,a.CDATE,a.CCY,a.HODING_TYPE ) D on A.PORTFOLIO_ID=D.PORTFOLIO_ID and A.ACCT_ID=D.ACCT_ID and A.CDATE=D.CDATE and A.CCY=D.CCY and A.HODING_TYPE = D.HODING_TYPE
and A.PORTFOLIO_ID = #{portfolioId}
and A.CDATE >= #{startCdate}
and A.CDATE <= #{endCdate}
union all select DISTINCT A.CDATE cdate, A.PORTFOLIO_ID portfolioId, A.PORTFOLIO_ID portfolioId1, A.ACCT_ID acctId, A.CCY ccy, A.HODING_TYPE hodingType, D.AMOUNT amount, A.AMOUNT amount1, C.PORTFOLIO_NAME portfolioName, B.BANK_DEP bankDep, B.ACCT_NAME acctName, B.LARGE_PAYNO largePayno, B.SWIFT_CODE swiftCode, concat(concat(concat(concat(D.PORTFOLIO_ID, D.CCY), D.CDATE), D.HODING_TYPE), D.ACCT_ID) AS upperPortfolioCode, '02' as hasChildren from PTL_CASH_POSITION_FLOW A inner join PTL_CASH_POSITION D on A.PORTFOLIO_ID = D.PORTFOLIO_ID and A.CCY = D.CCY and A.CDATE = D.CDATE and A.HODING_TYPE = D.HODING_TYPE and A.ACCT_ID = D.ACCT_ID inner join STL_CAPACCT_INFO B on D.ACCT_ID = B.ACCT_NO inner join PTL_PORTFOLIO C on A.PORTFOLIO_ID = C.PORTFOLIO_ID
and A.PORTFOLIO_ID = #{portfolioId}
and A.CDATE >= #{startCdate}
and A.CDATE <= #{endCdate}
